from collections import deque

def solve():
    line = input().split()

    if not line or line[0] == 'null':
        return

    # Build the tree from level-order serialization
    class TreeNode:
        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None

    root = TreeNode(int(line[0]))
    queue = deque([root])
    i = 1

    while queue and i < len(line):
        node = queue.popleft()
        # Left child
        if i < len(line):
            if line[i] != 'null':
                node.left = TreeNode(int(line[i]))
                queue.append(node.left)
            i += 1
        # Right child
        if i < len(line):
            if line[i] != 'null':
                node.right = TreeNode(int(line[i]))
                queue.append(node.right)
            i += 1

    # Level order traversal
    bfs_queue = deque([root])
    while bfs_queue:
        level_size = len(bfs_queue)
        level_vals = []
        for _ in range(level_size):
            node = bfs_queue.popleft()
            level_vals.append(str(node.val))
            if node.left:
                bfs_queue.append(node.left)
            if node.right:
                bfs_queue.append(node.right)
        print(' '.join(level_vals))

solve()

