from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree_from_level_order(tokens):
    if not tokens or tokens[0] == 'null':
        return None
    root = TreeNode(int(tokens[0]))
    queue = deque([root])
    i = 1
    while queue and i < len(tokens):
        node = queue.popleft()
        if i < len(tokens) and tokens[i] != 'null':
            node.left = TreeNode(int(tokens[i]))
            queue.append(node.left)
        i += 1
        if i < len(tokens) and tokens[i] != 'null':
            node.right = TreeNode(int(tokens[i]))
            queue.append(node.right)
        i += 1
    return root

def level_order_serialize(root):
    """Level-order (BFS) serialization with null markers."""
    if root is None:
        return '#'
    parts = []
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node is None:
            parts.append('#')
        else:
            parts.append(str(node.val))
            queue.append(node.left)
            queue.append(node.right)
    # Trim trailing nulls for compactness (not strictly required)
    while parts and parts[-1] == '#':
        parts.pop()
    return ','.join(parts) if parts else '#'

def level_order_deserialize(data):
    """Reconstruct tree from level-order serialized string."""
    if not data or data == '#':
        return None
    tokens = data.split(',')
    if not tokens or tokens[0] == '#':
        return None
    root = TreeNode(int(tokens[0]))
    queue = deque([root])
    i = 1
    while queue and i < len(tokens):
        node = queue.popleft()
        if i < len(tokens) and tokens[i] != '#':
            node.left = TreeNode(int(tokens[i]))
            queue.append(node.left)
        i += 1
        if i < len(tokens) and tokens[i] != '#':
            node.right = TreeNode(int(tokens[i]))
            queue.append(node.right)
        i += 1
    return root

def tree_to_level_order_string(root):
    if root is None:
        return 'null'
    result = []
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node is None:
            result.append('null')
        else:
            result.append(str(node.val))
            queue.append(node.left)
            queue.append(node.right)
